const { name, workspaceGid, teamGid, layout, notes, color } = $.input;

if (!name || !workspaceGid) throw new Error('name and workspaceGid are required');

const data = {
  data: {
    name,
    workspace: workspaceGid,
    default_view: layout || 'board'
  }
};

if (teamGid) data.data.team = teamGid;
if (notes) data.data.notes = notes;
if (color) data.data.color = color;

return data;

const sections = $.input.sections && $.input.sections.length > 0 ? $.input.sections : ['To Do', 'In Progress', 'Done'];
const projectGid = $.steps.createProject.response?.data?.gid;
if (!projectGid) throw new Error('Project creation failed - no GID returned');
return { sections: sections.map(name => ({ name })), projectGid };

const project = $.steps.createProject.response?.data || {};
const iterations = $.steps.createSections?.response?.iterations || [];
const createdSections = iterations.map(r => {
  const s = r?.createSection?.response?.data;
  return s ? { gid: s.gid, name: s.name } : null;
}).filter(Boolean);

return {
  projectGid: project.gid || '',
  name: project.name || '',
  layout: project.default_view || $.input.layout || 'board',
  permalink: project.permalink_url || '',
  sections: createdSections,
  sectionCount: createdSections.length,
  summary: `Created project "${project.name || $.input.name}" with ${createdSections.length} section${createdSections.length === 1 ? '' : 's'}: ${createdSections.map(s => s.name).join(', ')}`
};
